import static org.junit.Assert.assertTrue;

public class TimeSeries_createCopy_TriageGen0Test {

    private TimeSeries series;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");
        // Adding some dummy data to ensure the series is not empty
        series.add(new Second(new java.util.Date(1000L)), 10.0);
        series.add(new Second(new java.util.Date(2000L)), 20.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyStartLessThanZero() throws CloneNotSupportedException {
        series.createCopy(-1, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyEndLessThanStart() throws CloneNotSupportedException {
        series.createCopy(1, 0);
    }

    @Test
    public void testCreateCopyValidRange() throws CloneNotSupportedException {
        // The current implementation of createCopy has a 'if (false)' block 
        // which means the loop that copies items is unreachable.
        // We test the behavior as the code is written.

        TimeSeries copy = series.createCopy(0, 1);

        // Verify it is a different object instance
        assertNotSame(series, copy);

        // Verify metadata is reset as per code: copy.minY = Double.NaN; copy.maxY = Double.NaN;
        assertTrue(Double.isNaN(copy.getMinY()));
        assertTrue(Double.isNaN(copy.getMaxY()));

        // Verify data list is new and empty because the loop is unreachable due to 'if (false)'
        assertEquals(0, copy.getItemCount());

        // Verify it is a clone of the original structure (name, etc)
        assertEquals(series.getKey(), copy.getKey());
    }

    @Test
    public void testCreateCopyStartEqualsEnd() throws CloneNotSupportedException {
        // Testing the boundary where start == end
        TimeSeries copy = series.createCopy(0, 0);

        assertNotSame(series, copy);
        assertEquals(0, copy.getItemCount());
        assertTrue(Double.isNaN(copy.getMinY()));
    }

    @Test
    public void testCreateCopyLargeRange() throws CloneNotSupportedException {
        // Testing with a range larger than current size, though the loop is unreachable
        TimeSeries copy = series.createCopy(0, 100);

        assertNotSame(series, copy);
        assertEquals(0, copy.getItemCount());
    }
}
